{{ config(
            materialized='table',
                post_hook={
                    "sql": "ALTER SESSION SET TIMEZONE = \'Asia/Kolkata\'; create or replace table snitch_db.maplemonk.product_info as ( with inventory as ( select sku_group, date, sum(total_inventory) as inventory from snitch_db.maplemonk.cut_size_analysis group by 1,2 ), sales as ( select sku_group, order_timestamp::date as date, sum(gross_sales) as gross_sales, sum(quantity) as gross_quantity from snitch_db.maplemonk.fact_items_snitch where LOWER(IFNULL(discount_code, \'n\')) NOT LIKE \'%eco%\' AND LOWER(IFNULL(discount_code, \'n\')) NOT LIKE \'%influ%\' AND order_name NOT IN (\'2431093\',\'2422140\',\'2425364\',\'2430652\',\'2422237\',\'2420623\',\'2429832\',\'2422378\',\'2428311\',\'2429064\',\'2428204\',\'2421343\',\'2431206\',\'2430491\',\'2426682\',\'2426487\',\'2426458\',\'2423575\',\'2422431\',\'2423612\',\'2426625\',\'2428117\',\'2426894\',\'2425461\',\'2426570\',\'2423455\',\'2430777\',\'2426009\',\'2428245\',\'2427269\',\'2430946\',\'2425821\',\'2429986\',\'2429085\',\'2422047\',\'2430789\',\'2420219\',\'2428341\',\'2430444\',\'2426866\',\'2431230\',\'2425839\',\'2430980\',\'2427048\',\'2430597\',\'2420499\',\'2431050\',\'2420271\',\'2426684\',\'2428747\',\'2423523\',\'2431171\',\'2430830\',\'2425325\',\'2428414\',\'2429054\',\'2423596\') AND tags NOT IN (\'FLITS_LOGICERP\') group by 1,2 ), clicks as ( SELECT ga_date, sku_group, SUM(IFNULL(clicks, 0)) AS clicks FROM snitch_db.maplemonk.clicks_itemid GROUP BY 1, 2 ), metafields_data AS ( SELECT sku_group, id, price, product_name, product_type, occassion, print_design, collar AS meta_collar, material, sleeve_type, fit, style, color, closure, length, designs FROM snitch_db.maplemonk.metafields_data ), availability_master as ( select * from snitch_db.maplemonk.availability_master_v2 ) select inv.date, inv.sku_group, inv.inventory, sales.gross_sales, sales.gross_quantity, clicks.clicks, meta.price, meta.product_name, meta.product_type, meta.occassion, meta.print_design, meta.meta_collar, meta.material, meta.sleeve_type, meta.fit, meta.style, meta.color, meta.closure, meta.length, meta.designs, avail.final_ros, avail.natural_ros, avail.sales_last_7_days, avail.sales_last_15_days, avail.sales_last_30_days, avail.sku_class, avail.live_date, CASE WHEN LOWER(meta.print_design) LIKE \'%checks%\' THEN \'Checks\' WHEN LOWER(meta.print_design) LIKE \'%animal%\' THEN \'Animal Print\' WHEN LOWER(meta.print_design) LIKE \'%embroid%\' THEN \'Embroided\' WHEN LOWER(meta.print_design) LIKE \'%floral%\' THEN \'Floral\' WHEN LOWER(meta.print_design) LIKE \'%graphic%\' THEN \'Graphic Print\' WHEN LOWER(meta.print_design) LIKE \'%embellished%\' THEN \'Embellished\' WHEN LOWER(meta.print_design) LIKE \'%plain%\' THEN \'Solid\' WHEN LOWER(meta.print_design) LIKE \'%solid%\' THEN \'Solid\' WHEN LOWER(meta.print_design) LIKE \'%printed%\' THEN \'Printed\' WHEN LOWER(meta.print_design) LIKE \'%self%\' THEN \'Self Design\' WHEN LOWER(meta.print_design) LIKE \'%stripe%\' THEN \'Stripes\' WHEN LOWER(meta.print_design) LIKE \'%crochet%\' THEN \'Crochet\' WHEN LOWER(meta.print_design) LIKE \'%polka%\' THEN \'Polka Dots\' WHEN LOWER(meta.print_design) LIKE \'%geometric%\' THEN \'Geometric\' WHEN LOWER(meta.print_design) LIKE \'%tie &%\' THEN \'Tie & Dye\' WHEN LOWER(meta.print_design) LIKE \'%textured%\' THEN \'Textured\' WHEN meta.print_design IS NULL THEN \'Null\' ELSE \'Others\' END AS Designs_new, CASE WHEN LOWER(meta.meta_collar) LIKE \'%cuban%\' THEN \'Cuban\' WHEN LOWER(meta.meta_collar) LIKE \'%crew%\' THEN \'Round\' WHEN LOWER(meta.meta_collar) LIKE \'%round%\' THEN \'Round\' WHEN LOWER(meta.meta_collar) LIKE \'%polo%\' THEN \'Polo\' WHEN LOWER(meta.meta_collar) LIKE \'%high neck%\' THEN \'High Neck\' WHEN LOWER(meta.meta_collar) LIKE \'%spread%\' THEN \'Spread\' WHEN LOWER(meta.meta_collar) LIKE \'%button down%\' THEN \'Button Down\' WHEN LOWER(meta.meta_collar) LIKE \'%mandarin%\' THEN \'Mandarin\' WHEN LOWER(meta.meta_collar) LIKE \'%baseball%\' THEN \'Baseball\' WHEN LOWER(meta.meta_collar) LIKE \'%classic%\' THEN \'Classic\' WHEN LOWER(meta.meta_collar) LIKE \'%shawl%\' THEN \'Shawl\' WHEN LOWER(meta.meta_collar) LIKE \'%hooded%\' THEN \'Hooded\' WHEN LOWER(meta.meta_collar) LIKE \'%mock%\' THEN \'Round\' WHEN LOWER(meta.meta_collar) LIKE \'%turtleneck%\' THEN \'Turtle Neck\' WHEN LOWER(meta.meta_collar) LIKE \'%camp%\' THEN \'Cuban\' WHEN meta.meta_collar IS NULL THEN \'Null\' ELSE \'Others\' END AS Collar_New, CASE WHEN LOWER(meta.material) LIKE \'%cotton%\' THEN \'Cotton\' WHEN LOWER(meta.material) LIKE \'%poly%\' THEN \'Polyester\' WHEN LOWER(meta.material) LIKE \'%rayon%\' THEN \'Rayon\' WHEN LOWER(meta.material) LIKE \'%linen%\' THEN \'Linen\' WHEN LOWER(meta.material) LIKE \'%terry%\' THEN \'Terry\' WHEN LOWER(meta.material) LIKE \'%modal%\' THEN \'Modal\' WHEN LOWER(meta.material) LIKE \'%tencel%\' THEN \'Tencel\' WHEN LOWER(meta.material) LIKE \'%nylon%\' THEN \'Nylon\' WHEN LOWER(meta.material) LIKE \'%tencil%\' THEN \'Tencil\' WHEN LOWER(meta.material) LIKE \'%steel%\' THEN \'Stainless Steel\' WHEN meta.material IS NULL THEN \'Null\' ELSE \'Others\' END AS Material_New, from inventory inv left join sales sales on inv.date = sales.date and inv.sku_group = sales.sku_group left join clicks on inv.date = clicks.ga_date and inv.sku_group = clicks.sku_group left join metafields_data meta on inv.sku_group = meta.sku_group left join availability_master avail on inv.sku_group = avail.sku_group );",
                    "transaction": true
                }
            ) }}
            with sample_data as (

